const KEY='whkc-operations-v1';let stored;try{stored=JSON.parse(localStorage.getItem(KEY)||'null')}catch{}const S=stored||structuredClone(SEED);let role='O01',cid='',page='workbench',tab='todo',caseTab='process';
const uid=()=>Math.random().toString(36).slice(2)+Date.now().toString(36),today=()=>new Date().toISOString().slice(0,10),time=()=>new Date().toLocaleString('zh-CN',{hour12:false}),actor=()=>ROLES[role][1],C=id=>S.companies.find(c=>c.id===id),O=id=>S.orders.find(o=>o.id===id),K=id=>S.cases.find(k=>k.id===id);
function save(){localStorage.setItem(KEY,JSON.stringify(S))}function log(action,target,extra={}){S.logs.unshift({id:uid(),time:time(),actor:actor(),role,action,target,...extra});save()}
