function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3000)}
function b(n,fn,cls=''){return `<button class="${cls}" onclick="${fn}">${n}</button>`}function a(n,fn){return b(n,fn,'cell-action')}
function badge(s){return `<span class="badge ${/通过|完成|齐备|已核|已验|结项|强认证/.test(s)?'green':/待|缺|草稿|意向/.test(s)?'orange':/退|逾|不合|过期/.test(s)?'red':'blue'}">${esc(s)}</span>`}
function card(n,body,action=''){return `<section class="card"><div class="card-head"><h2>${n}</h2>${action}</div><div class="card-body">${body}</div></section>`}function notice(t){return `<div class="notice">${t}</div>`}
function table(headers,data){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${data.map(r=>`<tr>${r.map(v=>`<td>${v??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table>${!data.length?'<div class="empty">暂无符合条件的记录</div>':''}</div>`}
function add(t){$('#main').insertAdjacentHTML('beforeend',t)}function allow(...rs){if(rs.includes(role))return true;toast('此操作需要 '+rs.map(r=>ROLES[r]?.[0]||r).join(' / ')+'，请切换岗位身份演示');return false}
function authorized(){if(role==='O02')return S.companies.filter(c=>c.owner===actor());if(['O04','O06','S02'].includes(role))return S.companies.filter(c=>S.cases.some(k=>k.cid===c.id&&(role==='O04'?k.teacher===actor():role==='S02'?!!k.provider:true)));return S.companies}
function scope(list){return list.filter(r=>authorized().some(c=>c.id===r.cid)&&(!cid||r.cid===cid))}function orderScope(){return scope(S.orders)}function caseScope(){return scope(S.cases).filter(k=>role==='O04'?k.teacher===actor():role==='S02'?!!k.provider:true)}
function companyName(id){return role==='S02'?'武汉某科技企业（'+id.toUpperCase()+'）':esc(C(id)?.name||'—')}
function nav(){let last='';$('#nav').innerHTML=NAV.filter(n=>role!=='S02'||['workbench','masked'].includes(n[0])).map(n=>{let h=last===n[2]?'':`<div class="nav-group">${n[2]}</div>`;last=n[2];return h+`<a class="nav-item ${page===n[0]?'active':''}" href="#${n[0]}"><span class="nav-icon">${n[3]}</span>${n[1]}</a>`}).join('')}
function go(p,t){location.hash=p+(t?'/'+t:'')}function route(){let [p,t]=location.hash.slice(1).split('/');let n=NAV.find(n=>n[0]===p)||NAV[0];page=n[0];tab=n[4].includes(t)?t:n[4][0];nav();render()}
function render(){let n=NAV.find(n=>n[0]===page);$('#breadcrumb').innerHTML=`运营服务中心　/　${n[1]}　/　${LABELS[tab]}`;$('#companyButton').textContent=cid?'切换企业 ▾':'选择企业 ▾';$('#context').innerHTML=cid?`<div class="context-line"><span>当前企业：<b>${companyName(cid)}</b></span><span>认证：${C(cid).auth}</span><span>档案完整度：${C(cid).progress}%</span><span>订单 ${orderScope().length} · 项目 ${caseScope().length} · 材料 ${caseScope().reduce((s,k)=>s+k.materials.length,0)}</span><span>AI上下文：${C(cid).id} / v${S.contextVersion}</span>${a('清除企业筛选','clearCompany()')}</div>`:'尚未选择企业 · 当前显示授权范围内汇总，查看企业数据和代操作前需选择企业。';$('#main').innerHTML=`<div class="heading"><div><div class="eyebrow">${n[2]} / ${page.toUpperCase()}</div><h1>${n[1]}</h1><div class="subtitle">${ROLES[role][0]} · ${actor()}　｜　按功能表配置的岗位业务入口</div></div><span class="muted">${time().split(' ')[0]}</span></div><div class="tabs">${n[4].map(t=>b(LABELS[t],`go('${page}','${t}')`,tab===t?'active':'')).join('')}</div>`;const routes={workbench:workbench,clients:clients,business:business,delivery:delivery,quality:quality,acceptance:acceptance,finance:finance,support:support,providers:providers,masked:masked};routes[page]()}
function drawer(title,body,buttons=''){ $('#drawer').innerHTML=`<div class="drawer-head"><h2>${esc(title)}</h2>${b('✕','closeDrawer()')}</div><div class="drawer-body">${body}</div><div class="drawer-foot">${b('关闭','closeDrawer()')}${buttons}</div>`;$('#overlay').hidden=false}
function closeDrawer(){$('#overlay').hidden=true}$('#overlay').onclick=e=>{if(e.target===$('#overlay'))closeDrawer()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});
function form(title,fields,onSave,button='保存'){drawer(title,`<form id="actionForm"><div class="form-grid">${fields.map(([key,label,type,value,options])=>`<label class="field ${type==='textarea'?'wide':''}">${label}${type==='select'?`<select name="${key}">${options.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${key}" required>${esc(value)}</textarea>`:`<input name="${key}" type="${type||'text'}" ${type==='number'?'step="any"':''} value="${esc(value)}" ${type==='file'?'':'required'}>`}</label>`).join('')}</div></form>`,`<button class="primary" form="actionForm">${button}</button>`);$('#actionForm').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));for(const [key,,type] of fields)if(type==='file')v[key]=e.target.elements[key].files[0]?.name||'';if(onSave(v)===false)return;save();closeDrawer();render();toast('已保存，关联业务状态已更新')}}
