function companyPicker(callback){drawer('选择授权企业',notice('选择后同时切换档案、材料、项目、订单和AI上下文。')+authorized().map(c=>`<button class="company-choice" data-cid="${c.id}"><b>${companyName(c.id)}</b><small>${c.region} · ${c.auth} · 归属 ${role==='S02'?'平台商务':c.owner}</small></button>`).join(''));document.querySelectorAll('.company-choice').forEach(el=>el.onclick=()=>{cid=el.dataset.cid;S.contextVersion++;save();closeDrawer();render();callback?.(C(cid))})}
function clearCompany(){cid='';render()}function enterCompany(id,callback){if(!authorized().some(c=>c.id===id)){toast('不在授权企业范围');return}if(cid!==id){companyPicker(c=>{if(c.id===id)callback();else toast('请选择目标企业后重试')});return}callback()}
function tasks(){let ts=[];S.companies.filter(c=>authorized().some(a=>a.id===c.id)&&(!cid||c.id===cid)).forEach(c=>{if(['新分配','跟进中'].includes(c.status))ts.push({id:'follow'+c.id,title:'客户回访与需求跟进',kind:'待回访',role:'O02',cid:c.id,route:'business/follow',due:'2026-11-18'})});caseScope().forEach(k=>{let conf={'待分案':['待分配','O05','delivery/pool'],'待接单':['待接单','O04','delivery/cases'],'待复核':['待复核','O06','quality/pending'],'待整改':['待整改','O04','delivery/cases'],'待验收':['待验收','O02','acceptance']};if(conf[k.status]){let [kind,r,route]=conf[k.status];ts.push({id:k.id+kind,title:O(k.oid).product,kind,role:r,cid:k.cid,route,due:k.due})}});orderScope().filter(o=>o.invoice==='待开票').forEach(o=>ts.push({id:'inv'+o.id,title:o.product+' · '+o.no,kind:'待开票',role:'O07',cid:o.cid,route:'finance/invoices',due:'2026-11-19'}));return ts.filter(t=>['O03','O08'].includes(role)||t.role===role)}
function workbench(){if(tab==='proxy'){add(card('代操作与企业确认',table(['时间','企业','代操作人','内容','确认状态','操作'],scope(S.proxies).map(p=>[p.time,companyName(p.cid),p.actor,esc(p.action),badge(p.status),a('查看确认内容',`proxyDetail('${p.id}')`)]))));return}if(tab==='cockpit'){const all=orderScope(),ks=caseScope();add(notice('按当前岗位区分重点：商务总监关注转化与成交，交付负责人关注产能与逾期，财务关注收款和应收。所有指标可下钻。'));add(`<div class="report-six">${[['经营','¥'+all.reduce((s,o)=>s+o.amount,0).toLocaleString(),'business','orders'],['获客',authorized().length+' 家','business','mine'],['转化',all.filter(o=>o.status!=='意向单').length+' 单','business','orders'],['交付',ks.filter(k=>k.status==='交付中').length+' 项','delivery','cases'],['服务',scope(S.follow).length+' 次','business','follow'],['质检',ks.filter(k=>k.status==='待复核').length+' 项','quality','pending']].map(([n,v,p,t])=>`<div class="metric" onclick="go('${p}','${t}')"><label>${n}</label><strong>${v}</strong><small>点击查看明细 →</small></div>`).join('')}</div>`);add(card('当前岗位关注事项',role==='O07'?`已收款 ¥${all.reduce((s,o)=>s+o.paid,0)} · 应收 ¥${all.reduce((s,o)=>s+o.balance,0)}`:role==='O05'?`在办 ${ks.length} 项 · 逾期 ${ks.filter(k=>k.due<today()&&!['已验收','已结项'].includes(k.status)).length} 项`:'经营、获客、转化、交付、服务及质检数据均来自当前演示业务记录。'));return}
const ts=tasks(),done=S.tasksDone.filter(t=>t.actor===actor());add(`<div class="welcome"><div><h2>${actor()}，欢迎回到工作台</h2><div class="muted">${ROLES[role][0]} · 当前有 ${ts.length} 项业务待处理${cid?' · 已切换企业上下文':''}</div></div>${b(cid?'切换服务企业':'选择企业开始服务','companyPicker()','primary')}</div>`);add(`<div class="cards">${[['关联企业',authorized().length,'business','mine'],['在办项目',caseScope().length,'delivery','cases'],['临期 / 逾期',caseScope().filter(k=>k.due<='2026-11-19').length,'delivery','cases'],['订单与服务',orderScope().length,'business','orders']].map(([n,v,p,t])=>`<div class="metric metrics-click" onclick="go('${p}','${t}')"><label>${n}</label><strong>${v}</strong><small>查看明细 →</small></div>`).join('')}</div>`);
if(tab==='done'){add(card('已办记录',table(['时间','任务','处理人','操作'],done.map(d=>[d.time,esc(d.title),d.actor,a('查看业务',`go('${d.route.split('/')[0]}','${d.route.split('/')[1]||''}')`)]))));return}
add(`<section class="card"><div class="card-head"><h2>我的待办</h2><span class="muted">随业务处理自动更新</span></div><div class="toolbar"><select id="taskKind"><option value="">全部任务类型</option>${[...new Set(ts.map(t=>t.kind))].map(k=>`<option>${k}</option>`).join('')}</select><input id="taskQuery" placeholder="搜索企业 / 任务"><span class="spacer"></span>${b('批量查看','batchTasks()')}</div><div id="taskTable"></div></section>`);function draw(){const list=ts.filter(t=>(!$('#taskKind').value||t.kind===$('#taskKind').value)&&(t.title+companyName(t.cid)).includes($('#taskQuery').value));$('#taskTable').innerHTML=table(['选择','任务','企业','类型','截止日期','操作'],list.map(t=>[`<input type="checkbox" name="task" value="${t.id}">`,t.title,companyName(t.cid),badge(t.kind),t.due,a('去处理',`openTask('${t.id}')`)]))}$('#taskKind').onchange=draw;$('#taskQuery').oninput=draw;draw();add(card('消息提醒',S.notifications.filter(n=>!n.to||n.to===role).slice(0,4).map(n=>`<p>${esc(n.text)} <span class="muted">${n.time}</span></p>`).join('')||'<span class="muted">业务通知将随分案、付款、质检与审批自动产生。</span>'))}
function openTask(id){let t=tasks().find(t=>t.id===id);cid=t.cid;S.contextVersion++;save();go(...t.route.split('/'))}function batchTasks(){let list=[...document.querySelectorAll('[name=task]:checked')].map(e=>tasks().find(t=>t.id===e.value));if(!list.length){toast('请先选择任务');return}drawer('批量任务预览',table(['任务','类型','企业'],list.map(t=>[t.title,t.kind,companyName(t.cid)])),b('处理首项',`closeDrawer();openTask('${list[0].id}')`,'primary'))}function done(title,route){S.tasksDone.unshift({time:time(),actor:actor(),title,route});save()}
function clients(){const cs=authorized().filter(c=>!cid||c.id===cid);if(tab==='registration'){add(card('入驻审核队列',table(['企业','提交时间 / 区域','主体类型','信用代码','状态','领取人','操作'],cs.filter(c=>c.entry!=='已通过').map(c=>[companyName(c.id),'2026-11-15<br>'+c.region,'有限公司',c.credit,badge(c.entry),c.claimed||'未领取',a('领取',`claim('${c.id}')`)+a('核验 / 处理',`verify('${c.id}')`)]))));return}if(tab==='allocation'){add(notice('来源渠道、来源销售、推荐人和证据缺失时必须补录。核定时冻结归因快照；首次人工改派可由客服执行，再次改派需商务总监审批。'));add(card('待分配与当前归属',table(['企业','区域 / 行业','来源核定','当前归属','改派次数','操作'],cs.map(c=>[companyName(c.id),c.region+' / '+c.industry,badge(c.snapshot?'已核定':'待核定'),c.owner,c.reassign,a('核定 / 分配',`allocate('${c.id}')`)]))));add(card('区域自动分配规则（版本化）',table(['区域','行业','规模','商务经理','版本'],S.rules.map(r=>[r.region,r.industry,r.scale,r.manager,'v'+r.version])),b('调整规则','ruleForm()')));add(approvalsPanel('reassign'));return}if(tab==='source'){add(card('来源核定与补录',table(['企业','来源渠道','来源销售','推荐人','证据','操作'],cs.map(c=>[companyName(c.id),c.source||'待补录',c.sales||'待补录',c.referrer||'待补录',c.evidence||'待上传',a('补录并核定',`sourceForm('${c.id}')`)])),b('批量补录（Excel兼容CSV）','importSources()')));return}if(tab==='annual'){add(card('年度服务规划台账',table(['企业','年度','计划内容','截止时间','状态','操作'],scope(S.annual).map(p=>[companyName(p.cid),p.year,esc(p.plan),p.due,badge('免费计划 · 不生成订单'),a('手工建单',`manualAnnualOrder('${p.id}')`)])),b('新增年度规划','annualForm()','primary')));return}add(`<div class="toolbar"><input id="clientSearch" placeholder="企业 / 来源 / 商务销售"><select id="clientStatus"><option value="">全部状态</option>${['新分配','跟进中','已报价','已下单','交付中','已成交','沉默'].map(x=>`<option>${x}</option>`).join('')}</select><span class="spacer"></span>${b('申请导出客户台账','exportClients()')}</div><div id="clientTable"></div>`);const draw=()=>{$('#clientTable').innerHTML=card('企业客户台账',table(['企业','来源渠道 / 销售 / 推荐人','当前归属','档案完整度','签约 / 服务状态','操作'],cs.filter(c=>(c.name+c.source+c.sales+c.owner).includes($('#clientSearch').value)&&(!$('#clientStatus').value||c.status===$('#clientStatus').value)).map(c=>[companyName(c.id),`${c.source||'待补录'} / ${c.sales||'—'} / ${c.referrer||'—'}`,c.owner,`${c.progress}%<div class="progress"><span style="width:${c.progress}%"></span></div>`,badge(c.status),a('客户全景',`companyDetail('${c.id}')`)])))};$('#clientSearch').oninput=draw;$('#clientStatus').onchange=draw;draw();add(approvalsPanel('export'))}
function companyDetail(id){enterCompany(id,()=>{const c=C(id);drawer('客户全景 · '+c.name,`<dl class="detail-list"><dt>信用代码</dt><dd>${c.credit}</dd><dt>认证状态</dt><dd>${badge(c.auth)}</dd><dt>来源渠道 / 销售 / 推荐人</dt><dd>${esc([c.source,c.sales,c.referrer].join(' / '))}</dd><dt>历史归因快照</dt><dd>${esc(c.snapshot?JSON.stringify(c.snapshot):'未核定')}</dd><dt>当前归属</dt><dd>${c.owner}</dd><dt>合同 / 回款</dt><dd>${S.contracts.filter(x=>x.cid===id).length} 份合同 / 已付 ¥${S.orders.filter(o=>o.cid===id).reduce((s,o)=>s+o.paid,0)}</dd></dl><div class="history"><h3>来源与服务触点时间线</h3><ul class="timeline">${c.touches.map(t=>`<li>${esc(t.text)}<small>${t.time}</small></li>`).join('')}</ul></div>`,b('跟进客户',`closeDrawer();go('business','follow')`,'primary'))})}
function claim(id){if(!allow('O01'))return;C(id).claimed=actor();log('领取审核',C(id).name);render()}
function verify(id){if(!allow('O01'))return;enterCompany(id,()=>{let c=C(id);form('主体核验与审核',[['license','执照核对结果','select','一致',['一致','不一致','疑似重复主体','疑似异常主体']],['action','处理结论','select','通过',['通过','退回补正','合并重复主体','挂靠主企业','拒绝']],['target','关联主体 / 依据说明','textarea','核对执照企业名称与18位信用代码，记录核验依据。']],v=>{if(v.license!=='一致'&&v.action==='通过'){toast('主体异常不能直接通过');return false}c.entry=v.action==='通过'?'已通过':v.action==='退回补正'?'待补正':v.action;c.auditBasis=v.target;log('主体核验：'+v.action,c.name);done('入驻审核 '+c.name,'clients/registration');notify(c.name+'审核结果：'+v.action,'O02')})})}
function sourceForm(id,after){if(!allow('O01'))return;let c=C(id);form('来源补录与人工核定',[['source','来源渠道','text',c.source],['sales','来源销售','select',c.sales||'周晴',['周晴','李明','陈一鸣','王琳']],['referrer','推荐人（无则填无）','text',c.referrer||'无'],['evidence','来源证据','file','']],v=>{if(!v.evidence&&!c.evidence){toast('请上传来源证据');return false}Object.assign(c,{source:v.source,sales:v.sales,referrer:v.referrer,evidence:v.evidence||c.evidence});if(!c.snapshot)c.snapshot={source:c.source,sales:c.sales,referrer:c.referrer,time:time(),actor:actor(),method:'人工核定'};log('来源人工核定',c.name);if(after)setTimeout(after,0)})}
function allocate(id){if(!allow('O01'))return;let c=C(id);if(!c.snapshot||!c.source||!c.sales||!c.referrer||!c.evidence){sourceForm(id,()=>allocate(id));return}form('商务分配 / 改派',[['mode','分配方式','select','区域规则自动分配',['区域规则自动分配','手动改派']],['manager','商务经理','select',c.owner,['周晴','李明']],['reason','分配 / 改派理由','textarea','按区域、行业与规模匹配。']],v=>{const rule=S.rules.find(r=>r.region===c.region&&(r.industry==='全部'||r.industry===c.industry)&&(r.scale==='全部'||r.scale===c.scale));let manager=v.mode==='区域规则自动分配'?rule?.manager:v.manager;if(!manager){toast('未匹配规则，请选择手动改派');return false}if(c.owner!==manager&&c.reassign>=1){S.approvals.unshift({id:uid(),type:'reassign',cid:id,manager,reason:v.reason,actor:actor(),status:'待审批'});notify(c.name+'再次改派需审批','O03')}else{if(c.owner!==manager)c.reassign++;c.owner=manager;c.status='新分配';notify(c.name+'已分配给'+manager,'O02')}log('商务分配',c.name,{reason:v.reason})})}
function ruleForm(){if(!allow('O01'))return;form('区域分配规则',[['region','区域','select','东湖高新区',['东湖高新区','武昌区','洪山区']],['industry','行业','text','全部'],['scale','规模','text','全部'],['manager','商务经理','select','周晴',['周晴','李明']]],v=>{let r=S.rules.find(r=>r.region===v.region&&r.industry===v.industry&&r.scale===v.scale);if(r)Object.assign(r,v,{version:r.version+1});else S.rules.push({...v,version:1});log('修改分配规则',v.region)})}
function approvalsPanel(type){return card('审批与处理记录',table(['事项','发起人','状态','操作'],S.approvals.filter(x=>x.type===type).map(x=>[type==='export'?'客户台账导出':companyName(x.cid)+'改派',x.actor,badge(x.status),x.status==='待审批'?a('总监审批',`approve('${x.id}')`):'已处理'])))}
function approve(id){if(!allow('O03'))return;let p=S.approvals.find(x=>x.id===id);form('商务总监审批',[['decision','结论','select','通过',['通过','退回']],['reason','审批意见','textarea','']],v=>{p.status=v.decision==='通过'?'已通过':'已退回';p.comment=v.reason;if(v.decision==='通过'){if(p.type==='reassign'){let c=C(p.cid);c.owner=p.manager;c.reassign++;notify(c.name+'已改派','O02')}else downloadCSV(p.data,'客户台账')}log('审批'+p.status,p.type)})}
function importSources(){if(!allow('O01'))return;drawer('批量来源补录',notice('在Excel中按“企业名称、来源渠道、来源销售、推荐人、证据”五列整理，另存UTF-8 CSV后导入。原型不解析二进制.xlsx。')+`<input type="file" id="sourceFile" accept=".csv"><p id="importResult" class="muted"></p>`,b('导入并核定','commitImport()','primary'))}
async function commitImport(){let f=$('#sourceFile').files[0];if(!f){toast('请选择CSV');return}let lines=(await f.text()).replace(/^\uFEFF/,'').trim().split(/\r?\n/).slice(1).map(x=>x.split(',').map(v=>v.replace(/^"|"$/g,'')));if(lines.some(r=>r.length!==5||r.some(v=>!v.trim())||!S.companies.some(c=>c.name===r[0]))){toast('导入失败：请核对5列内容、企业名称及必填值');return}for(let [name,source,sales,referrer,evidence] of lines){let c=S.companies.find(c=>c.name===name);Object.assign(c,{source,sales,referrer,evidence});if(!c.snapshot)c.snapshot={source,sales,referrer,time:time(),actor:actor(),method:'批量人工核定'}}log('批量来源核定',lines.length+'家企业');closeDrawer();render();toast('批量补录已完成，历史归因快照保留')}
function exportClients(){if(!allow('O01','O09'))return;form('申请客户台账导出',[['reason','用途','textarea','']],v=>{S.approvals.unshift({id:uid(),type:'export',actor:actor(),status:'待审批',reason:v.reason,data:[['企业','渠道','来源销售','推荐人','当前归属'],...authorized().filter(c=>!cid||c.id===cid).map(c=>[c.name,c.source,c.sales,c.referrer,c.owner])]});log('申请导出','客户台账')})}
function annualForm(){if(!allow('O09'))return;chooseFirst(c=>form('年度服务规划',[['year','年度','number',2027],['plan','免费年度规划','textarea',''],['due','临期提醒日期','date','2027-01-15']],v=>{S.annual.push({id:uid(),cid:c.id,...v});log('登记年度规划',c.name)}))}
function manualAnnualOrder(id){if(!allow('O09','O02'))return;const p=S.annual.find(p=>p.id===id);cid=p.cid;newOrder(p.plan)}
function business(){if(tab==='mine'){add(card('名下企业',table(['企业','状态','档案完整度','最近跟进','操作'],authorized().filter(c=>(!cid||c.id===cid)&&(role!=='O02'||c.owner===actor())).map(c=>[companyName(c.id),badge(c.status),c.progress+'%',c.last,a('企业全景',`companyDetail('${c.id}')`)+a('选择企业',`cid='${c.id}';render()`)]))));return}if(tab==='follow'){add(card('拜访与跟进记录',table(['企业','方式 / 对象','诉求','下一步 / 提醒','附件','记录人'],scope(S.follow).map(f=>[companyName(f.cid),f.method+' / '+f.contact,esc(f.need),esc(f.next)+' / '+f.remind,esc(f.file||'—'),f.actor])),b('新增跟进','followForm()','primary')));return}if(tab==='archive'){if(!cid){add(card('建档协助','<div class="empty">请先选择服务企业<br>'+b('选择企业','companyPicker()','primary')+'</div>'));return}let c=C(cid);add(notice('商务代录不会直接覆盖正式档案，经企业确认后生效。'));add(card('正式企业档案',table(['年度收入（万元）','研发投入（万元）','知识产权数量'],[[c.archive.revenue,c.archive.rd,c.archive.patents]]),b('商务代录','archiveForm()','primary')));add(card('待确认变更',table(['代操作人','内容','企业确认','操作'],scope(S.proxies).filter(p=>p.kind==='archive').map(p=>[p.actor,esc(p.action),badge(p.status),a('确认流程',`proxyDetail('${p.id}')`)]))));return}if(tab==='share'){add(card('个人带参分享链接',notice('仅具有销售身份的账号可生成链接。点击、注册、绑定、下单统计为演示数据，真实统计需接入服务。')+table(['落地页','分享链接','点击 / 注册 / 绑定 / 下单','操作'],S.shares.filter(s=>s.actor===actor()).map(s=>[s.landing,esc(s.url),[s.clicks,s.register,s.bind,s.order].join(' / '),a('复制查看',`shareDetail('${s.id}')`)])),b('生成个人链接','shareForm()','primary')));return}if(tab==='payment'){add(card('催付与开票提醒',table(['企业 / 订单','订单状态','待收金额','发票状态','操作'],orderScope().map(o=>[companyName(o.cid)+'<div class="muted">'+o.no+'</div>',badge(o.status),'¥'+o.balance,badge(o.invoice),a('催付',`remind('${o.id}','付款')`)+a('申请开票',`requestInvoice('${o.id}')`)]))));return}add(card('意向与订单',table(['订单 / 企业','服务商品','金额 / 已收','服务状态','企业确认','操作'],orderScope().map(o=>[o.no+'<div class="muted">'+companyName(o.cid)+'</div>',o.product,'¥'+o.amount+' / ¥'+o.paid,badge(o.status),badge(o.confirmed?'已确认':'待企业确认'),a('详情',`orderDetail('${o.id}')`)+(o.status==='意向单'?a('转正式订单',`convertOrder('${o.id}')`):'')])),b('新建意向单','newOrder()','primary')))}
function followForm(){if(!allow('O02'))return;chooseFirst(c=>form('拜访与跟进',[['method','方式','select','电话',['电话','现场拜访','企业微信','语音转写']],['contact','沟通对象','text',c.contact],['need','诉求 / 语音转写文本','textarea',''],['next','下一步','textarea',''],['remind','提醒时间','datetime-local','2026-11-20T10:00'],['file','附件 / 语音文件','file','']],v=>{S.follow.push({id:uid(),cid:c.id,...v,actor:actor()});c.last=today();c.status='跟进中';c.touches.push({time:time(),text:actor()+'跟进：'+v.need});log('商务跟进',c.name);done('客户回访 '+c.name,'business/follow')}))}
function proxy(kind,company,action,payload){S.proxies.unshift({id:uid(),cid:company.id,kind,action,payload,actor:actor(),role,time:time(),status:'待企业确认'});log('代操作',company.name,{proxy:true,confirmation:'待企业确认'});notify(company.name+'有内容待企业确认')}
function archiveForm(){if(!allow('O02'))return;let c=C(cid);form('商务代录企业档案',[['revenue','营业收入（万元）','number',c.archive.revenue],['rd','研发投入（万元）','number',c.archive.rd],['patents','有效知识产权数量','number',c.archive.patents]],v=>proxy('archive',c,'商务代录年度档案',v),'代录并提交企业确认')}
function proxyDetail(id){let p=S.proxies.find(p=>p.id===id);drawer('代操作确认记录',notice('下方为企业确认演示入口。实际产品应由企业账号确认，平台代操作人不能替企业自动通过。')+`<dl class="detail-list"><dt>企业</dt><dd>${companyName(p.cid)}</dd><dt>代操作人</dt><dd>${p.actor} / ${p.role}</dd><dt>操作</dt><dd>${p.action}</dd><dt>提交时间</dt><dd>${p.time}</dd><dt>确认状态</dt><dd>${badge(p.status)}</dd><dt>待确认内容</dt><dd>${esc(JSON.stringify(p.payload,null,2))}</dd></dl>`,p.status==='待企业确认'?b('模拟企业拒绝',`confirmProxy('${id}',false)`)+b('模拟企业确认',`confirmProxy('${id}',true)`,'primary'):'')}
function confirmProxy(id,yes){let p=S.proxies.find(p=>p.id===id);p.status=yes?'企业已确认':'企业已拒绝';p.confirmedBy='企业管理员（模拟）';p.confirmedAt=time();if(yes){if(p.kind==='archive'){Object.assign(C(p.cid).archive,p.payload);C(p.cid).progress=95}if(p.kind==='order'){let o=O(p.payload.oid);o.confirmed=true;o.status='待付款';C(p.cid).status='已下单'}if(p.kind==='plan'){let k=K(p.payload.kid);k.planConfirmed=true}}S.logs.unshift({id:uid(),time:time(),actor:'企业管理员（模拟）',action:p.status,target:C(p.cid).name});save();closeDrawer();render();toast('企业确认状态已更新')}
function newOrder(prefill=''){if(!allow('O02','O09'))return;chooseFirst(c=>form('新建意向单',[['product','服务商品','text','高新技术企业认定辅导'],['amount','服务金额（元）','number',29800],['days','服务周期（天）','number',45],['scope','服务范围与责任','textarea',prefill||''],['type','订单类型','select','托管',['托管','自主']]],v=>{S.orders.unshift({id:uid(),no:'ORD'+Date.now(),cid:c.id,...v,amount:Number(v.amount),paid:0,balance:Number(v.amount),manager:actor(),status:'意向单',confirmed:false,invoice:'未申请'});c.status='已报价';log('建立意向单',c.name)}))}
function orderDetail(id){let o=O(id);enterCompany(o.cid,()=>drawer('订单详情 · '+o.no,`<div class="order-steps"><span>意向</span>→<span>企业确认</span>→<span>付款核款</span>→<span>分案交付</span>→<span>质检验收</span>→<span>结果与尾款</span></div><dl class="detail-list"><dt>企业</dt><dd>${companyName(o.cid)}</dd><dt>绑定等级</dt><dd>${C(o.cid).auth}（转单放行，深度开工前须强认证）</dd><dt>服务商品</dt><dd>${esc(o.product)}</dd><dt>服务范围</dt><dd>${esc(o.scope)}</dd><dt>周期</dt><dd>${o.days}天</dd><dt>总额 / 已收 / 余额</dt><dd>¥${o.amount} / ¥${o.paid} / ¥${o.balance}</dd><dt>责任人</dt><dd>${o.manager}</dd><dt>状态</dt><dd>${badge(o.status)}</dd></dl>`))}
function convertOrder(id){if(!allow('O02','O09'))return;let o=O(id);o.status='待企业确认';proxy('order',C(o.cid),'意向单转正式订单',{oid:id,scope:o.scope,amount:o.amount,days:o.days,manager:o.manager});render();toast('已提交企业确认，弱绑定企业可继续下单')}
function remind(id,type){if(!allow('O02'))return;let o=O(id);notify(o.no+'：请处理'+type);log('催付提醒',o.no);toast('已发送站内提醒（原型）')}
function requestInvoice(id){if(!allow('O02','O01'))return;let o=O(id);if(o.paid<=0){toast('尚未核款，不能申请开票');return}o.invoice='待开票';notify(o.no+'申请开票','O07');log('申请开票',o.no);render()}
function shareForm(){if(!allow('O02','O01','O04','O09'))return;form('生成个人分享链接',[['landing','落地页','select','科创体检',['科创体检','政策中心','服务商城']]],v=>{const path=v.landing==='科创体检'?'questionnaire.html':'prototype.html';S.shares.push({id:uid(),actor:actor(),landing:v.landing,url:new URL(path,location.href).href+'?sales='+encodeURIComponent(actor())+'&source=share',clicks:0,register:0,bind:0,order:0});log('生成带参分享链接',actor())})}function shareDetail(id){let s=S.shares.find(s=>s.id===id);drawer('带参分享链接',`<label class="field">个人链接<textarea readonly>${esc(s.url)}</textarea></label><p class="muted">可选中复制分享。参数绑定当前销售身份，实际失效规则由管理后台配置。</p>`)}
function caseTable(list,action='办理'){return table(['案件 / 企业','项目 / 金额','老师 / 服务商','内部时限','状态','操作'],list.map(k=>[k.id.toUpperCase()+'<div class="muted">'+companyName(k.cid)+'</div>',esc(O(k.oid).product)+'<div class="muted">¥'+O(k.oid).amount+'</div>',esc(k.teacher||k.provider||'待分配'),(k.urgent?'<span class="risk">加急</span> ':'')+k.due,badge(k.status),a(action,`caseDetail('${k.id}')`)+(['O05'].includes(role)?a('分案 / 改派',`assignCase('${k.id}')`):'')]))}
function delivery(){if(tab==='load'){const teachers=['陈一鸣','吴老师','张老师'];add(card('咨询老师负载与可用工时',table(['老师','在办数','逾期数','能力标签','可用工时','操作'],teachers.map((t,i)=>[t,S.cases.filter(k=>k.teacher===t).length,S.cases.filter(k=>k.teacher===t&&k.due<today()).length,['高企、财务','专精特新、规划','知识产权、成果转化'][i],40-S.cases.filter(k=>k.teacher===t).length*8+'小时',a('去分案',"go('delivery','pool')")]))));return}if(tab==='pool'){const ready=orderScope().filter(o=>o.confirmed&&o.paid>0&&!S.cases.some(k=>k.oid===o.id));add(card('付款后待建案订单',table(['订单','企业','项目','操作'],ready.map(o=>[o.no,companyName(o.cid),o.product,a('进入案件池',`createCase('${o.id}')`)]))));add(card('待分案队列',caseTable(caseScope().filter(k=>['待分案','已拒单'].includes(k.status)).sort((a,b)=>a.due.localeCompare(b.due)))));return}if(tab==='receipt'){add(notice('托管项目须登记官方回执号、提交时间和附件，才能完成企业验收。'));add(card('代交回执登记',table(['案件','企业','项目类型','回执号','状态','操作'],caseScope().map(k=>[k.id,companyName(k.cid),O(k.oid).type,k.receipt?.no||'未登记',badge(k.receipt?'已登记':'待登记'),a('登记回执',`receiptForm('${k.id}')`)]))));return}if(tab==='results'){add(card('申报结果与结项',table(['案件','企业','申报结果','尾款应收','操作'],caseScope().map(k=>[k.id,companyName(k.cid),badge(k.result?.result||'待登记'),'¥'+(O(k.oid).tailDue?O(k.oid).balance:0),a('登记结果',`resultForm('${k.id}')`)]))));return}add(card('我的案件',caseTable(caseScope())))}
function createCase(oid){if(!allow('O05'))return;let o=O(oid);if(!o.confirmed||o.paid<=0){toast('需已确认且已付款');return}S.cases.push({id:uid(),oid,cid:o.cid,status:'待分案',teacher:'',provider:'',due:'2026-12-20',urgent:false,requirements:o.scope,materials:[{name:'营业执照',state:'缺失',file:''}],chapters:[{name:'申报正文',text:'',final:false}],packages:[],checks:[],rectifications:[],experts:[]});log('订单建案',o.no);render()}
function assignCase(id){if(!allow('O05'))return;let k=K(id);form('分案与改派',[['target','承接方类型','select','咨询老师',['咨询老师','服务商兜底']],['person','承接老师 / 服务商','select','陈一鸣',['陈一鸣','吴老师','张老师','楚天科创服务商']],['due','内部交付时限','date',k.due],['requirements','交付结果要求','textarea',k.requirements],['reason','分案 / 改派理由','textarea','按能力、区域和当前负载分配']],v=>{if((v.target==='服务商兜底')!==(v.person==='楚天科创服务商')){toast('承接类型与承接人不一致');return false}k.teacher=v.target==='咨询老师'?v.person:'';k.provider=v.target==='服务商兜底'?v.person:'';Object.assign(k,{due:v.due,requirements:v.requirements,status:'待接单',assignedAt:time()});notify('案件 '+k.id+' 已派单给 '+v.person,v.target==='咨询老师'?'O04':'S02');log('案件分派',k.id,{reason:v.reason})})}
function caseDetail(id){let k=K(id);enterCompany(k.cid,()=>{if(role==='S02'){maskedDetail(id);return}drawer('案件办理 · '+O(k.oid).product,`<div class="notice">${companyName(k.cid)}　${badge(k.status)}　责任人 ${k.teacher||k.provider||'待分配'}　截止 ${k.due}</div><div class="pill-nav">${['过程','材料','诊断','年度计划','申报书','专家审核','封包','整改'].map((s,i)=>b(s,`caseSection('${id}',${i})`)).join('')}</div><div id="caseBody"></div>`);caseSection(id,0)})}
function caseSection(id,index){let k=K(id);if(!$('#caseBody'))return;const actions=()=>allow('O04');if(index===0){$('#caseBody').innerHTML=`<dl class="detail-list"><dt>交付要求</dt><dd>${esc(k.requirements)}</dd><dt>认证状态</dt><dd>${badge(C(k.cid).auth)}</dd><dt>首轮材料清单</dt><dd>${k.materials.map(m=>m.name).join('、')}</dd><dt>开工时间</dt><dd>${k.started||'未开工'}</dd></dl><div class="toolbar">${b('接单',`acceptCase('${id}')`,'primary')}${b('拒单',`rejectCase('${id}')`)}${b('确认开工',`startCase('${id}')`,'primary')}</div>`}if(index===1){$('#caseBody').innerHTML=table(['材料','状态','文件','操作'],k.materials.map((m,i)=>[m.name,badge(m.state),esc(m.file||'未上传'),a('核对与补齐',`materialForm('${id}',${i})`)]))+notice('缺失、过期或不合规材料会生成补齐任务，齐备之前不能封包。')}if(index===2){$('#caseBody').innerHTML=`<h3>诊断草稿（仅内部可见）</h3><textarea id="diagnosis" class="doc-editor">${esc(k.draft||'')}</textarea><div class="toolbar">${b('生成示例草稿',`generateDiagnosis('${id}')`)}${b('保存人工修订',`saveDiagnosis('${id}')`,'primary')}</div><p class="muted">定稿随封包进入质检复核后才对外。</p>`}if(index===3){$('#caseBody').innerHTML=`<h3>年度申报计划与任务初稿</h3><textarea id="planText" class="doc-editor" placeholder="任务、交付成果、责任人、截止时间">${esc(k.plan||'')}</textarea><p>${badge(k.planConfirmed?'企业已确认':'待编制 / 待确认')}</p>${b('提交企业确认',`submitPlan('${id}')`,'primary')}`}if(index===4){$('#caseBody').innerHTML=table(['章节','撰写状态','操作'],k.chapters.map((c,i)=>[c.name,badge(c.final?'人工定稿':'草稿'),a('章节撰写',`chapterEditor('${id}',${i})`)]))}if(index===5){$('#caseBody').innerHTML=notice(O(k.oid).type==='托管'?'托管项目：专家送审免费。':'自主项目：需登记付费确认后送审。')+table(['专家','意见','回复','状态'],k.experts.map(e=>[esc(e.expert),esc(e.comment),esc(e.reply),badge(e.status)]))+b('送专家审核',`expertForm('${id}')`,'primary')+b('记录专家意见 / 回复',`expertFeedback('${id}')`)}if(index===6){$('#caseBody').innerHTML=table(['版本','封包人','时间','材料 / 检查快照'],k.packages.map(p=>['v'+p.version,p.actor,p.time,a('查看固定版本',`packageDetail('${id}',${p.version})`)]))+`<p class="muted">每次封包固定材料文件名、章节与检查结果，旧版本保留。</p>`+b('封包并提交质检',`packageCase('${id}')`,'primary')}if(index===7){$('#caseBody').innerHTML=table(['整改项','责任人','截止时间','状态','操作'],k.rectifications.map((r,i)=>[esc(r.item),esc(r.owner),r.due,badge(r.done?'已处理':'待整改'),a('记录整改',`rectifyForm('${id}',${i})`)]))}}
function acceptCase(id){if(!allow('O04','S02'))return;let k=K(id);if(k.status!=='待接单'){toast('当前不在待接单状态');return}k.status='已接单';log('接单',id);closeDrawer();render()}
function rejectCase(id){if(!allow('O04','S02'))return;form('拒单理由',[['reason','拒单理由','textarea','']],v=>{let k=K(id);k.status='已拒单';k.rejectReason=v.reason;k.reassignDeadline=Date.now()+86400000;notify('案件'+id+'拒单，须24小时内改派','O05');log('拒单',id,{reason:v.reason})})}
function startCase(id){if(!allow('O04','S02'))return;let k=K(id);if(k.status!=='已接单'){toast('请先接单');return}if(C(k.cid).auth!=='强认证'){notify('请协助'+C(k.cid).name+'完成强认证','O02');toast('深度服务开工前必须强认证，已提醒商务');return}k.status='交付中';k.started=time();log('确认开工',id);closeDrawer();render()}
function materialForm(id,index){if(!allow('O04','S02'))return;let m=K(id).materials[index];form('材料核对与补齐',[['status','材料状态','select',m.state,['齐备','缺失','过期','不合规']],['file','材料文件','file',''],['note','检查说明 / 补齐任务','textarea','核对材料真实性、有效期与主体一致性']],v=>{if(v.status==='齐备'&&!v.file&&!m.file){toast('齐备材料须有文件');return false}m.state=v.status;m.file=v.file||m.file;m.note=v.note;if(v.status!=='齐备')notify(m.name+'需补齐：'+v.note);log('核对材料',id+' / '+m.name)})}
function generateDiagnosis(id){if(!allow('O04'))return;let c=C(K(id).cid);$('#diagnosis').value=`【AI示例草稿，须人工核实】\n企业年收入${c.archive.revenue}万元，研发投入${c.archive.rd}万元，知识产权${c.archive.patents}项。建议核实研发费用口径及知识产权有效性，再制定申报计划。`}
function saveDiagnosis(id){if(!allow('O04'))return;K(id).draft=$('#diagnosis').value;log('保存诊断草稿',id);toast('已保存内部草稿')}
function submitPlan(id){if(!allow('O04'))return;let k=K(id),text=$('#planText').value.trim();if(!text){toast('请编制任务、成果、责任人与截止时间');return}k.plan=text;k.planConfirmed=false;proxy('plan',C(k.cid),'年度申报计划提交确认',{kid:id,plan:text});closeDrawer();render();toast('年度计划已提交企业确认')}
function chapterEditor(id,index){if(!allow('O04'))return;let c=K(id).chapters[index];drawer('申报书章节 · '+c.name,`<textarea id="chapterText" class="doc-editor">${esc(c.text)}</textarea><p class="muted">示例AI辅助不连接模型服务，内容须人工复核。</p><div class="toolbar">${b('AI示例初稿',`$('#chapterText').value='【示例初稿】'+C(K('${id}').cid).name+'：${esc(c.name)}。请根据已核实档案和证据完善。'`)}${b('一致性检查',`toast($('#chapterText').value.trim()?'请核对年度、金额、主体和证据引用，当前文本'+$('#chapterText').value.length+'字':'章节为空')`)}</div>`,b('保存草稿',`saveChapter('${id}',${index},false)`)+b('人工定稿',`saveChapter('${id}',${index},true)`,'primary'))}
function saveChapter(id,i,final){let text=$('#chapterText').value.trim();if(!text){toast('章节内容不能为空');return}Object.assign(K(id).chapters[i],{text,final});log(final?'章节人工定稿':'保存章节',id);caseDetail(id);caseSection(id,4)}
function expertForm(id){if(!allow('O04'))return;form('专家送审',[['expert','专家','select','赵教授',['赵教授','吴教授']],['paid','费用状态','select',O(K(id).oid).type==='托管'?'托管免费':'待付费',['托管免费','已付费','待付费']],['materials','送审材料说明','textarea','']],v=>{if(O(K(id).oid).type==='自主'&&v.paid!=='已付费'){toast('自主项目先确认付费');return false}K(id).experts.push({...v,comment:'待专家意见',reply:'',status:'送审中'});log('专家送审',id)})}
function expertFeedback(id){if(!allow('O04'))return;let e=K(id).experts.at(-1);if(!e){toast('请先送审');return}form('专家意见与回复',[['comment','专家意见（演示录入）','textarea',e.comment],['reply','整改回复','textarea',e.reply]],v=>{Object.assign(e,v,{status:'已回复'});log('记录专家意见回复',id)})}
function packageCase(id){if(!allow('O04','S02'))return;let k=K(id);if(k.materials.some(m=>m.state!=='齐备'||!m.file)){toast('材料未齐备，不能封包');return}if(k.chapters.some(c=>!c.final)){toast('请先完成所有章节人工定稿');return}if(k.rectifications.some(r=>!r.done)){toast('尚有整改项未处理');return}if(k.status!=='交付中'&&k.status!=='待整改'){toast('当前状态不能封包');return}k.packages.push({version:k.packages.length+1,time:time(),actor:actor(),materials:structuredClone(k.materials),chapters:structuredClone(k.chapters),checks:structuredClone(k.checks)});k.status='待复核';k.checks=[];notify('案件'+id+'已提交质检','O06');log('固定封包版本',id);done('案件封包 '+id,'delivery/cases');closeDrawer();render();toast('已固定版本并进入质检队列')}
function packageDetail(id,version){let p=K(id).packages.find(p=>p.version===version);drawer('不可变封包版本 v'+version,`<p>${p.time} · ${p.actor}</p><h3>材料快照</h3>${table(['材料','文件','状态'],p.materials.map(m=>[m.name,esc(m.file),m.state]))}<h3 style="margin-top:20px">章节快照</h3>${p.chapters.map(c=>`<h3>${c.name}</h3><p>${esc(c.text)}</p>`).join('')}`)}
function rectifyForm(id,index){if(!allow('O04','S02'))return;let r=K(id).rectifications[index];form('整改处理',[['reply','处理说明','textarea',r.reply||'']],v=>{r.reply=v.reply;r.done=true;log('整改处理',id+' / '+r.item)})}
function receiptForm(id){if(!allow('O04'))return;form('登记官方申报回执',[['no','回执号','text',K(id).receipt?.no||''],['submitted','官方提交时间','datetime-local','2026-11-16T10:00'],['file','回执附件','file','']],v=>{if(!v.file){toast('请上传回执附件');return false}K(id).receipt=v;log('代交回执登记',id)})}
function resultForm(id){if(!allow('O04'))return;let k=K(id);if(k.status!=='已验收'){toast('企业完成验收后才能登记结果结项');return}form('申报结果与结项',[['result','结果','select','通过',['通过','未通过']],['publication','公示链接 / 结果说明','textarea','']],v=>{k.result={...v,time:time()};let o=O(k.oid);o.result=v.result;if(v.result==='通过'){k.status='已结项';o.status='尾款待付';o.tailDue='2026-12-16';notify(o.no+'尾款应收¥'+o.balance,'O02')}else{k.status='减免复核';o.status='待减免复核';notify(o.no+'申报未通过，请复核减免','O07')}C(k.cid).touches.push({time:time(),text:o.product+'结果：'+v.result});log('登记申报结果',id)})}
function quality(){let ks=caseScope().filter(k=>tab==='pending'?k.status==='待复核':tab==='rectify'?k.rectifications.length:['待验收','已验收','已结项'].includes(k.status));add(card(LABELS[tab],caseTable(ks,tab==='sample'?'抽检':'查看案件')));if(tab==='rectify')add(card('整改时限与升级',table(['案件','整改项','责任人','截止时间','进度'],ks.flatMap(k=>k.rectifications.map(r=>[k.id,esc(r.item),esc(r.owner),r.due,badge(r.done?'已处理':r.due<today()?'逾期 · 升级交付负责人':'待整改')])))));if(tab==='sample')add(card('抽检统计',`已抽检 ${ks.filter(k=>k.sampled).length} 项，发现漏检 ${ks.filter(k=>k.sampleFailed).length} 项`,b('按50%比例抽检','sampleCases()')));if(tab==='pending')add(card('质检检查',notice('选中“执行复核”逐项检查，退回必须列明整改项、责任人和时限。')+table(['案件','封包版本','提交人','预检','操作'],ks.map(k=>[k.id,'v'+k.packages.length,k.packages.at(-1)?.actor||'—',k.materials.every(m=>m.state==='齐备')?'材料齐备':'缺失',a('执行复核',`reviewCase('${k.id}')`)]))))}
function reviewCase(id){if(!allow('O06'))return;const k=K(id);if(k.packages.at(-1)?.actor===actor()){toast('提交与复核不可同人');return}drawer('执行质检 · '+id,`<div class="checklist">${['完整性','一致性','合规性','敏感词','数值勾稽','材料有效性'].map((n,i)=>`<label><input type="checkbox" name="qualityCheck" value="${n}" ${k.checks.includes(n)?'checked':''}>${n}检查通过</label>`).join('')}</div><label class="field" style="margin-top:25px">复核意见<textarea id="qualityReason"></textarea></label>`,b('退回整改',`returnCase('${id}')`)+b('通过复核',`passCase('${id}')`,'primary'))}
function passCase(id){if(!allow('O06'))return;let checks=[...document.querySelectorAll('[name=qualityCheck]:checked')].map(c=>c.value);if(checks.length!==6){toast('须逐项完成全部检查');return}let k=K(id);k.checks=checks;k.status='待验收';k.reviewBy=actor();notify('案件'+id+'已通过质检，待企业验收','O02');log('质检通过',id);done('质检 '+id,'quality/pending');closeDrawer();render()}
function returnCase(id){if(!allow('O06'))return;form('退回整改（必填整改项）',[['item','整改项','textarea',''],['owner','责任人','text',K(id).teacher||'服务商经办'],['due','整改截止时间','date','2026-11-20']],v=>{let k=K(id);k.rectifications.push({...v,done:false});k.status='待整改';notify('案件'+id+'需整改：'+v.item,'O04');log('质检退回',id)})}
function sampleCases(){if(!allow('O06'))return;let ks=caseScope().filter(k=>['待验收','已验收','已结项'].includes(k.status));ks.slice(0,Math.ceil(ks.length*.5)).forEach(k=>k.sampled=true);log('发起抽检','比例50%');render();toast('已标记抽检案件，请逐项复核并记录漏检')}
function acceptance(){add(card('企业验收',table(['案件','企业','质检','官方回执','企业确认','操作'],caseScope().filter(k=>['待验收','已验收'].includes(k.status)).map(k=>[k.id,companyName(k.cid),badge('已通过'),k.receipt?.no||'未登记',badge(k.status),a('验收详情',`acceptanceForm('${k.id}')`)]))))}
function acceptanceForm(id){if(!allow('O02'))return;let k=K(id);enterCompany(k.cid,()=>form('企业验收确认（模拟企业操作）',[['decision','企业验收结论','select','通过',['通过','退回']],['note','验收意见 / 整改项','textarea',''],['due','退回整改时限','date','2026-11-25']],v=>{if(v.decision==='通过'){if(O(k.oid).type==='托管'&&!k.receipt){toast('托管项目缺少官方回执，不能完成验收');return false}k.status='已验收';k.acceptance={actor:'企业管理员（模拟）',time:time(),note:v.note};O(k.oid).status='已验收';log('企业验收通过（模拟）',id);done('验收 '+id,'acceptance')}else{k.status='待整改';k.rectifications.push({item:v.note,owner:k.teacher||k.provider,due:v.due,done:false});log('企业验收退回（模拟）',id)}}))}
function finance(){if(tab==='receipts'){add(card('银行收款认领',notice('一笔收款可拆分到多个订单，同一订单可合并多笔收款。核款与开票须使用不同财务经办身份。')+table(['付款方','金额 / 时间','回单','认领金额','状态','操作'],S.payments.filter(p=>!cid||p.claims.some(c=>O(c.oid)?.cid===cid)||p.payer===C(cid).name).map(p=>[esc(p.payer),'¥'+p.amount+' / '+p.time,esc(p.voucher),'¥'+p.claims.reduce((s,c)=>s+c.amount,0),badge(p.status),a('认领',`claimPayment('${p.id}')`)+a('核款',`verifyPayment('${p.id}')`)])),b('登记银行收款','paymentForm()','primary')));return}if(tab==='invoices'){add(notice('同一经办人不得同时核款和开票，可使用“切换财务经办人”演示职责隔离。'));add(card('开票申请队列',table(['订单 / 企业','实付金额','开票状态','操作'],orderScope().filter(o=>o.invoice==='待开票').map(o=>[o.no+'<div class="muted">'+companyName(o.cid)+'</div>','¥'+o.paid,badge(o.invoice),a('开票处理',`invoiceForm('${o.id}')`)])),b('切换财务经办人','switchFinanceActor()')));add(card('发票与寄送台账',table(['企业','发票号','金额 / 类型','发票文件','寄送 / 签收','操作'],scope(S.invoices).map(i=>[companyName(i.cid),esc(i.no),'¥'+i.amount+' / '+i.type,esc(i.file),esc(i.ship||'未登记')+' / '+(i.signed?'已签收':'待签收'),a('寄送登记',`shipInvoice('${i.id}')`)]))));return}if(tab==='refunds'){add(card('退款申请与执行',table(['企业 / 订单','原实付 / 扣减 / 退款','商务确认','财务审批','退款状态','操作'],scope(S.refunds).map(r=>[companyName(r.cid)+' / '+O(r.oid).no,'¥'+r.original+' / ¥'+r.deduct+' / ¥'+r.amount,badge(r.business?'已确认':'待商务确认'),badge(r.approved?'已批准':'待财务审批'),badge(r.status),a('商务确认',`refundStep('${r.id}','business')`)+a('财务审批',`refundStep('${r.id}','approve')`)+a('执行退款',`refundStep('${r.id}','execute')`)])),b('新增退款申请','refundForm()','primary')));return}add(card('收款与开票台账',table(['企业','订单','应收 / 已收 / 余额','开票金额','对账结果'],orderScope().map(o=>[companyName(o.cid),o.no,'¥'+o.amount+' / ¥'+o.paid+' / ¥'+o.balance,'¥'+S.invoices.filter(i=>i.oid===o.id).reduce((s,i)=>s+i.amount,0),badge(o.paid>=S.invoices.filter(i=>i.oid===o.id).reduce((s,i)=>s+i.amount,0)?'可核对':'开票差异')])),b('导出台账','exportFinance()')))}
let financeName='赵敏';function switchFinanceActor(){if(!allow('O07'))return;financeName=financeName==='赵敏'?'孙宁':'赵敏';toast('当前财务经办：'+financeName)}
function paymentForm(){if(!allow('O07'))return;form('登记银行回款',[['payer','付款方','text',''],['amount','金额（元）','number',''],['time','收款时间','date',today()],['voucher','银行回单','file','']],v=>{if(Number(v.amount)<=0||!v.voucher){toast('请填写正金额并上传回单');return false}S.payments.unshift({id:uid(),...v,amount:Number(v.amount),claims:[],status:'待认领',claimBy:''});log('登记银行回款',v.payer)})}
function claimPayment(id){if(!allow('O07'))return;const p=S.payments.find(p=>p.id===id);if(p.status==='已核款'){toast('已核款记录不可修改');return}drawer('收款拆分 / 合并认领',`<p>付款方：${esc(p.payer)} · 收款金额 ¥${p.amount}</p><form id="claimsForm">${orderScope().map(o=>`<label class="field" style="margin:15px 0">${o.no} · ${companyName(o.cid)} · 剩余应收 ¥${o.balance}<input name="${o.id}" type="number" min="0" step="0.01" value="${p.claims.find(c=>c.oid===o.id)?.amount||0}"></label>`).join('')}</form>`,`<button class="primary" form="claimsForm">保存认领</button>`);$('#claimsForm').onsubmit=e=>{e.preventDefault();let claims=Object.entries(Object.fromEntries(new FormData(e.target))).filter(([,v])=>Number(v)>0).map(([oid,v])=>({oid,amount:Number(v)}));if(claims.reduce((s,c)=>s+c.amount,0)>p.amount||claims.some(c=>c.amount>O(c.oid).balance)){toast('认领超过收款金额或订单应收');return}if(!claims.length){toast('至少认领一个订单');return}p.claims=claims;p.status=claims.reduce((s,c)=>s+c.amount,0)===p.amount?'待核款':'差异挂账';p.claimBy=financeName;log('收款认领',p.payer);closeDrawer();render()}}
function verifyPayment(id){if(!allow('O07'))return;let p=S.payments.find(p=>p.id===id);if(p.status==='已核款'){toast('该回款已核款');return}if(!p.claims.length){toast('请先认领订单');return}if(p.claims.reduce((s,c)=>s+c.amount,0)!==p.amount){p.status='差异挂账';notify('收款差异请商务确认：'+p.payer,'O02');save();render();toast('收款差异已挂账并通知商务');return}if(p.claims.some(c=>c.amount>O(c.oid).balance)){toast('订单应收已变化，请重新认领');return}p.claims.forEach(c=>{let o=O(c.oid);o.paid+=c.amount;o.balance=o.amount-o.paid;o.status='已付款';o.invoice='待开票';o.verifiedBy=financeName;notify(o.no+'付款已确认，待开票','O07');notify(o.no+'付款已确认','O02')});p.status='已核款';log('核款确认',p.payer,{financeActor:financeName});done('核款 '+p.payer,'finance/receipts');render()}
function invoiceForm(id){if(!allow('O07'))return;let o=O(id);if(o.verifiedBy===financeName){toast('核款人与开票人不可相同，请切换财务经办人');return}form('发票处理',[['no','发票号码','text',''],['type','发票类型','select','电子发票',['电子发票','纸质发票']],['amount','金额（元）','number',o.paid-S.invoices.filter(i=>i.oid===id).reduce((s,i)=>s+i.amount,0)],['title','企业抬头','text',C(o.cid).name],['file','发票文件','file','']],v=>{if(!v.file||Number(v.amount)<=0||Number(v.amount)+S.invoices.filter(i=>i.oid===id).reduce((s,i)=>s+i.amount,0)>o.paid){toast('请核对文件与开票金额，累计不能超过实付');return false}S.invoices.push({id:uid(),cid:o.cid,oid:id,...v,amount:Number(v.amount),actor:financeName,ship:v.type==='电子发票'?'电子推送（模拟）':'',signed:false});o.invoice='已开票';notify(o.no+'发票已开具');log('开票处理',o.no,{financeActor:financeName})})}
function shipInvoice(id){if(!allow('O07'))return;let i=S.invoices.find(x=>x.id===id);form('寄送与签收',[['method','寄送方式','select','快递',['快递','自取','电子推送']],['no','快递单号 / 推送记录','text',i.ship||''],['signed','签收状态','select','待签收',['待签收','已签收']]],v=>{i.ship=v.method+' '+v.no;i.signed=v.signed==='已签收';log('发票寄送登记',i.no)})}
function refundForm(){if(!allow('O02','O07'))return;chooseFirst(c=>{let os=S.orders.filter(o=>o.cid===c.id&&o.paid>0);if(!os.length){toast('没有已付款订单');return}form('退款核算申请',[['oid','原订单','select',os[0].id,os.map(o=>o.id)],['deduct','服务扣减金额（元）','number',0],['items','扣减项与退款理由','textarea',''],['account','原路退款企业账户','text',c.name],['verified','弱绑定人工账户核实','select',c.auth==='强认证'?'主体一致':'待核实',['主体一致','人工核实通过','待核实']]],v=>{let o=O(v.oid),remaining=o.paid-S.refunds.filter(r=>r.oid===o.id&&r.status!=='已退回').reduce((s,r)=>s+r.amount,0),amount=remaining-Number(v.deduct);if(amount<=0||Number(v.deduct)<0){toast('退款金额须大于零，扣减不能超过可退余额');return false}if(v.account!==c.name||(c.auth==='弱绑定'&&v.verified!=='人工核实通过')){toast('退款账户须与企业主体一致；弱绑定须人工核实');return false}S.refunds.push({id:uid(),cid:c.id,oid:o.id,original:remaining,deduct:Number(v.deduct),amount,items:v.items,account:v.account,business:false,approved:false,status:'待商务确认'});log('申请退款',o.no)})})}
function refundStep(id,step){let r=S.refunds.find(x=>x.id===id);if(r.status==='已退款'){toast('退款已完成');return}if(step==='business'){if(!allow('O02'))return;r.business=true;r.status='待财务审批'}else if(step==='approve'){if(!allow('O07'))return;if(!r.business){toast('请先由商务确认');return}r.approved=true;r.approvedBy=financeName;r.status='待执行'}else{if(!allow('O07'))return;if(!r.approved){toast('请先完成财务审批');return}let o=O(r.oid);if(r.amount>o.paid){toast('订单实付已变化，请重新核算');return}o.paid-=r.amount;o.balance=0;o.status='已退款';r.status='已退款';notify(o.no+'已按企业账户原路退款（模拟）')}log('退款'+step,O(r.oid).no);render()}
function exportFinance(){if(!allow('O07'))return;downloadCSV([['企业','订单','应收','已收','余额'],...orderScope().map(o=>[C(o.cid).name,o.no,o.amount,o.paid,o.balance])],'收款开票台账');log('导出财务台账','财务与结算')}
function support(){if(tab==='knowledge'){add(card('百问百答维护',`<p class="muted">个人目标：50 条 · 当前本人 ${S.knowledge.filter(q=>q.owner===actor()).length} 条。到期答案须重新评审。</p>`+table(['问题','答案','维护人','评审到期','状态','操作'],S.knowledge.map(q=>[esc(q.question),esc(q.answer).slice(0,45)+'…',q.owner,q.review,badge(q.review<today()?'待复审':q.status),a('编辑 / 评审',`knowledgeForm('${q.id}')`)])),b('新增问答','knowledgeForm()','primary')));return}add(card('合同模板与寄送回签',notice('合同金额直接取自订单，不能手动修改。')+table(['企业 / 订单','合同模板','金额','寄送 / 回签','操作'],scope(S.contracts).map(c=>[companyName(c.cid)+' / '+O(c.oid).no,c.template,'¥'+O(c.oid).amount,esc(c.ship||'未寄送')+' / '+(c.signed?'已回签':'待回签'),a('寄送回签',`contractShip('${c.id}')`)])),b('从订单生成合同','contractForm()','primary')))}
function knowledgeForm(id){if(!allow('O01'))return;let q=S.knowledge.find(q=>q.id===id);form('问答维护与评审',[['question','常见问题','text',q?.question||''],['answer','标准答案','textarea',q?.answer||''],['review','下次评审日期','date',q?.review||'2027-01-01']],v=>{if(q)Object.assign(q,v,{status:'有效'});else S.knowledge.push({id:uid(),...v,owner:actor(),status:'有效'});log('维护问答',v.question)})}
function contractForm(){if(!allow('O01'))return;chooseFirst(c=>{let os=S.orders.filter(o=>o.cid===c.id&&o.status!=='意向单');if(!os.length){toast('请先形成正式订单');return}form('按订单生成合同',[['oid','关联订单（金额从订单读取）','select',os[0].id,os.map(o=>o.id)],['template','合同模板','select','科技服务委托合同2026',['科技服务委托合同2026','咨询服务协议2026']]],v=>{S.contracts.push({id:uid(),cid:c.id,...v,ship:'',signed:false});log('生成合同',O(v.oid).no)})})}
function contractShip(id){if(!allow('O01'))return;let c=S.contracts.find(x=>x.id===id);form('合同寄送与回签',[['ship','寄送方式与单号','text',c.ship],['signed','回签状态','select',c.signed?'已回签':'待回签',['已回签','待回签']],['file','回签文件','file','']],v=>{if(v.signed==='已回签'&&!v.file&&!c.file){toast('请上传回签文件');return false}Object.assign(c,{ship:v.ship,signed:v.signed==='已回签',file:v.file||c.file});log('登记合同寄送回签',c.id)})}
function providers(){add(notice('服务商仅能在独立脱敏视图查看已指派案件；客户端不展示服务商信息。拒单后交付负责人需及时改派。'));add(card('服务商派单与节点跟踪',table(['案件','承接服务商','接单 / 开工','交付节点','拒单改派时限','操作'],caseScope().filter(k=>k.provider).map(k=>[k.id,esc(k.provider),k.started||k.status,badge(k.status),k.reassignDeadline?new Date(k.reassignDeadline).toLocaleString():'—',a('改派',`assignCase('${k.id}')`)])),b('从案件池派单',"go('delivery','pool')",'primary')))}
function masked(){if(role!=='S02'){add(notice('请切换为“服务商经办（脱敏）”身份查看。'));return}add(card('我的指派案件',table(['案件','企业（脱敏）','项目要求','材料数','交付时限','操作'],caseScope().map(k=>[k.id,companyName(k.cid),esc(k.requirements),k.materials.length,k.due,a('案件详情',`maskedDetail('${k.id}')`)]))))}
function maskedDetail(id){if(role!=='S02'||!K(id).provider){toast('仅服务商可查看已指派的脱敏案件');return}let k=K(id);cid=k.cid;drawer('脱敏案件 · '+id,`<dl class="detail-list"><dt>企业</dt><dd>${companyName(k.cid)}</dd><dt>联系人</dt><dd>企业联系人（平台转达）</dd><dt>交付要求</dt><dd>${esc(k.requirements)}</dd><dt>时限</dt><dd>${k.due}</dd><dt>状态</dt><dd>${badge(k.status)}</dd></dl><div class="toolbar">${b('接单',`acceptCase('${id}')`)}${b('拒单',`rejectCase('${id}')`)}${b('确认开工',`startCase('${id}')`)}</div>${table(['材料','状态','操作'],k.materials.map((m,i)=>[m.name,badge(m.state),a('补齐',`materialForm('${id}',${i})`)]))}<p class="muted">仅展示当前指派任务，不展示真实企业名称、联系方式、订单金额和商务归属。</p>`)}
function downloadCSV(data,name){const text='\ufeff'+data.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(',')).join('\r\n');let url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));let link=document.createElement('a');link.href=url;link.download=name+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function coverage(){drawer('运营端功能表 · 逐项对照',`<p class="muted">按原始工作表实际51条有效功能记录映射。标题63条但中间序号有缺项；S02为原表指定的服务商经办角色。</p>${OPS_FEATURES.map(f=>`<div style="padding:14px 0;border-bottom:1px solid var(--line)"><b>${f.number}. ${esc(f.name)}</b><p class="muted">${esc(f.description)}</p><a href="#${f.route}" onclick="closeDrawer()">进入对应页面 →</a><span class="muted">　主责 ${f.role}</span></div>`).join('')}`)}
const ROLE_PAGES={O01:['workbench','clients','support'],O02:['workbench','clients','business','acceptance','finance'],O03:['workbench','clients','business'],O04:['workbench','delivery'],O05:['workbench','delivery','providers'],O06:['workbench','quality'],O07:['workbench','finance'],O08:['workbench','clients','business','delivery','quality','acceptance','finance','support','providers'],O09:['workbench','clients','business'],S02:['workbench','masked']};
const baseNav=nav;nav=function(){baseNav();document.querySelectorAll('.nav-item').forEach(el=>{if(!ROLE_PAGES[role].includes(el.hash.slice(1)))el.style.display='none'})};
const baseRender=render;render=function(){if(!ROLE_PAGES[role].includes(page)){$('#main').innerHTML='<h1>当前岗位无此页面入口</h1>'+notice('请从左侧岗位菜单进入，或切换相应演示身份。');return}baseRender();if(page==='workbench'&&tab==='todo'&&['O01','O05'].includes(role)){$('.toolbar').insertAdjacentHTML('beforeend',b('批量领取','batchClaim()'))}if(page==='quality'&&tab==='sample'){add(card('抽检执行记录',table(['案件','抽检状态','发现漏检','操作'],caseScope().filter(k=>k.sampled).map(k=>[k.id,badge(k.sampleResult||'待检查'),k.sampleFailed?'是':'—',a('记录抽检',`sampleForm('${k.id}')`)]))))}};
function batchClaim(){const chosen=[...document.querySelectorAll('[name=task]:checked')].map(e=>tasks().find(t=>t.id===e.value));if(!chosen.length){toast('请先勾选待办任务');return}chosen.forEach(t=>{if(t.kind==='待审核'&&role==='O01')C(t.cid).claimed=actor();if(t.kind==='待分配'&&role==='O05'){let k=S.cases.find(k=>t.id.startsWith(k.id));if(k)k.claimed=actor()}});log('批量领取',chosen.length+'项待办');render();toast('任务已领取，业务审批仍需逐项核对')}
function sampleForm(id){if(!allow('O06'))return;form('抽检结果',[['result','结论','select','未发现漏检',['未发现漏检','发现漏检']],['note','检查说明与整改建议','textarea','']],v=>{let k=K(id);k.sampleResult=v.result;k.sampleFailed=v.result==='发现漏检';k.sampleNote=v.note;if(k.sampleFailed)notify('案件'+id+'抽检发现漏检，计入质检质量记录','O05');log('抽检结果',id)})}
const baseRoleChange=()=>{cid='';S.contextVersion++;save();page=role==='S02'?'masked':'workbench';tab=role==='S02'?'masked':'todo';location.hash=page;nav();render();toast('已切换岗位，企业上下文已清空')};
$('#role').innerHTML=Object.entries(ROLES).map(([r,[name,person]])=>`<option value="${r}">${r} ${name} · ${person}</option>`).join('');$('#role').onchange=e=>{role=e.target.value;baseRoleChange()};window.addEventListener('hashchange',route);route();
